//! Replays the PHP 8.5.13 / Twig 3.31.1 oracle vectors in `tests/vectors/preg_match.json`.
//!
//! The vectors are generated by `tests/vectors/preg_match.gen.php` (see its header for the format). Regenerate
//! from the repository root (Git Bash, Docker image `twig-oracle:3.31.1` from `research/php-oracle`):
//!
//! ```text
//! MSYS_NO_PATHCONV=1 docker run --rm -v "$(cygpath -wa crates/twig-pcre/tests/vectors):/v:ro" \
//!     twig-oracle:3.31.1 php /v/preg_match.gen.php > crates/twig-pcre/tests/vectors/preg_match.json
//! ```
//!
//! Every group was produced by one fresh PHP process and is replayed here on one fresh `Pcre`, step by step,
//! so state carried between calls (pattern cache, JIT switched off after an allocation failure, ini
//! settings) is compared too. `groups` were recorded with PHP's default `pcre.jit=1`, `groups_nojit` with
//! `pcre.jit=0` from the start; a build without the JIT replays only the latter.

use serde_json::Value;
use twig_pcre::preg::{MatchKey, MatchValue, PregMatch};
use twig_pcre::{DiagnosticLevel, Pcre, SubjectUtf8};

const VECTORS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors/preg_match.json");

/// Byte strings in failure reports: printable ASCII as is, everything else as `\xNN`.
#[derive(PartialEq)]
struct B(Vec<u8>);

impl std::fmt::Debug for B {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("b\"")?;
        for &c in &self.0 {
            match c {
                b'"' | b'\\' => write!(f, "\\{}", c as char)?,
                0x20..=0x7E => write!(f, "{}", c as char)?,
                _ => write!(f, "\\x{c:02X}")?,
            }
        }
        f.write_str("\"")
    }
}

fn hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex string");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex digit"))
        .collect()
}

/// A byte string of the vector format: a JSON string, `{"hex": ...}` or `{"rep": ..., "n": ...}`.
fn bytes(v: &Value) -> Vec<u8> {
    match v {
        Value::String(s) => s.as_bytes().to_vec(),
        Value::Object(o) if o.contains_key("hex") => hex(o["hex"].as_str().expect("hex string")),
        Value::Object(o) if o.contains_key("rep") => {
            let n = o["n"].as_u64().expect("rep count") as usize;
            let mut out = bytes(&o["prefix"]);
            out.extend(bytes(&o["rep"]).repeat(n));
            out.extend(bytes(&o["suffix"]));
            out
        }
        other => panic!("not a byte string: {other}"),
    }
}

fn show(b: &[u8]) -> String {
    let s = String::from_utf8_lossy(b);
    if s.chars().count() > 80 {
        format!(
            "{}... ({} bytes)",
            s.chars().take(80).collect::<String>(),
            b.len()
        )
    } else {
        format!("{s:?}")
    }
}

fn result_of(v: &Value) -> Option<i64> {
    match v {
        Value::Bool(false) => None,
        Value::Number(n) => Some(n.as_i64().expect("int result")),
        other => panic!("bad result {other}"),
    }
}

fn warnings_of(v: &Value) -> Vec<(DiagnosticLevel, B)> {
    v.as_array()
        .expect("warnings array")
        .iter()
        .map(|w| {
            let level = match w[0].as_i64() {
                Some(2) => DiagnosticLevel::Warning,
                Some(8) => DiagnosticLevel::Notice,
                other => panic!("unexpected errno {other:?}"),
            };
            (level, B(bytes(&w[1])))
        })
        .collect()
}

fn matches_of(v: &Value) -> Option<Vec<(MatchKey, MatchValue)>> {
    let entries = match v {
        Value::Null => return None,
        Value::Array(a) => a,
        other => panic!("bad matches {other}"),
    };
    let value = |v: &Value| -> MatchValue {
        match v {
            Value::Null => MatchValue::Null,
            Value::Array(pair) => {
                let text = if pair[0].is_null() {
                    None
                } else {
                    Some(bytes(&pair[0]))
                };
                MatchValue::Pair(text, pair[1].as_i64().expect("offset"))
            }
            other => MatchValue::Str(bytes(other)),
        }
    };
    Some(
        entries
            .iter()
            .map(|e| {
                let key = match &e[0] {
                    Value::Number(n) => MatchKey::Index(n.as_i64().expect("int key")),
                    other => MatchKey::Name(bytes(other)),
                };
                (key, value(&e[1]))
            })
            .collect(),
    )
}

struct Failures {
    list: Vec<String>,
    checks: usize,
}

impl Failures {
    fn check<T: PartialEq + std::fmt::Debug>(
        &mut self,
        what: impl FnOnce() -> String,
        expected: T,
        actual: T,
    ) {
        self.checks += 1;
        if expected != actual {
            self.list.push(format!(
                "{}\n    expected: {expected:?}\n    actual:   {actual:?}",
                what()
            ));
        }
    }
}

fn utf8_mode(v: &Value) -> SubjectUtf8 {
    match v.as_str() {
        Some("auto") | None => SubjectUtf8::Auto,
        Some("flagged") => SubjectUtf8::Flagged,
        Some("unflagged") => SubjectUtf8::Unflagged,
        Some(other) => panic!("bad utf8 mode {other}"),
    }
}

/// Applies `ini_set()` calls given as `[[name, value], ...]`, in order.
fn apply_ini(pcre: &mut Pcre, ini: &[Value]) {
    for pair in ini {
        let (name, value) = (
            pair[0].as_str().expect("ini name"),
            pair[1].as_str().expect("ini value"),
        );
        match name {
            "pcre.backtrack_limit" => {
                pcre.set_backtrack_limit(value.parse().expect("integer ini value"))
            }
            "pcre.recursion_limit" => {
                pcre.set_recursion_limit(value.parse().expect("integer ini value"))
            }
            "pcre.jit" => pcre.set_jit(value != "0"),
            other => panic!("unsupported ini setting {other}"),
        }
    }
}

fn run_case(pcre: &mut Pcre, group: &str, index: usize, step: &Value, f: &mut Failures) {
    let pattern = bytes(&step["p"]);
    let subject = bytes(&step["s"]);
    let utf8 = utf8_mode(&step["utf8"]);
    let flags = step["flags"].as_i64().unwrap_or(0);
    let offset = step["offset"].as_i64().unwrap_or(0);
    let ctx = |op: &str, field: &str| {
        format!(
            "[{group} #{index}] {op}.{field}: pattern {} subject {} ({utf8:?})",
            show(&pattern),
            show(&subject)
        )
    };
    for op in step["ops"].as_array().expect("ops") {
        let kind = op["op"].as_str().expect("op kind");
        match kind {
            "match" => {
                let mut diags = Vec::new();
                let result = pcre.preg_match_ex(&pattern, &subject, utf8, &mut |d| {
                    diags.push((d.level, B(d.text())))
                });
                f.check(|| ctx(kind, "result"), result_of(&op["result"]), result);
                f.check(
                    || ctx(kind, "warnings"),
                    warnings_of(&op["warnings"]),
                    diags,
                );
                f.check(
                    || ctx(kind, "error"),
                    op["error"].as_i64().expect("error"),
                    pcre.last_error().code(),
                );
            }
            "twig_runtime" => {
                let actual = pcre
                    .twig_matches_ex(&pattern, &subject, utf8)
                    .map_err(|e| B(e.message(&pattern)));
                let expected = match op.get("ok") {
                    Some(ok) => Ok(ok.as_i64().expect("ok int")),
                    None => Err(B(bytes(&op["error"]))),
                };
                f.check(|| ctx(kind, "outcome"), expected, actual);
            }
            "twig_compile" => {
                let actual = pcre.twig_validate_constant(&pattern).map_err(B);
                let expected = if op["error"].is_null() {
                    Ok(())
                } else {
                    Err(B(bytes(&op["error"])))
                };
                f.check(|| ctx(kind, "outcome"), expected, actual);
            }
            "twig_compile_null" => {
                let expected = if op["error"].is_null() {
                    Ok(())
                } else {
                    Err(B(bytes(&op["error"])))
                };
                f.check(
                    || ctx(kind, "outcome"),
                    expected,
                    Err(B(twig_pcre::null_constant_regexp_error())),
                );
                f.check(
                    || ctx(kind, "last_error"),
                    op["last_error"].as_i64().expect("last_error"),
                    pcre.last_error().code(),
                );
            }
            "captures" => {
                let mut diags = Vec::new();
                let actual =
                    pcre.preg_match_captures(&pattern, &subject, flags, offset, utf8, &mut |d| {
                        diags.push((d.level, B(d.text())));
                    });
                match (op.get("value_error"), actual) {
                    (Some(expected), Err(e)) => f.check(
                        || ctx(kind, "value_error"),
                        expected.as_str().expect("message").to_owned(),
                        e.message,
                    ),
                    (Some(expected), Ok(r)) => f.check(
                        || ctx(kind, "value_error"),
                        format!("ValueError {expected}"),
                        format!("{r:?}"),
                    ),
                    (None, Err(e)) => f.check(
                        || ctx(kind, "value_error"),
                        "no ValueError".to_owned(),
                        e.message,
                    ),
                    (None, Ok(PregMatch { result, matches })) => {
                        f.check(|| ctx(kind, "result"), result_of(&op["result"]), result);
                        f.check(
                            || ctx(kind, "error"),
                            op["error"].as_i64().expect("error"),
                            pcre.last_error().code(),
                        );
                        f.check(|| ctx(kind, "matches"), matches_of(&op["matches"]), matches);
                    }
                }
                f.check(
                    || ctx(kind, "warnings"),
                    warnings_of(&op["warnings"]),
                    diags,
                );
            }
            other => panic!("unknown op {other}"),
        }
    }
}

#[test]
fn preg_match_oracle_vectors() {
    let text = std::fs::read_to_string(VECTORS).expect("read preg_match.json");
    let root: Value = serde_json::from_str(&text).expect("parse preg_match.json");
    assert_eq!(root["php"], "8.5.13");
    assert_eq!(
        root["pcre"],
        twig_pcre::pcre2::Config::get().version.as_str()
    );
    let jit = Pcre::new().jit_supported();

    let mut f = Failures {
        list: Vec::new(),
        checks: 0,
    };
    let mut cases = 0;
    // "groups" record PHP's default pcre.jit=1. Without the JIT (no `jit` feature, or an architecture
    // sljit does not support) limits are reached at other points, so only "groups_nojit" (PHP with
    // pcre.jit=0, i.e. the interpreter) applies; a JIT build replays both, the latter after set_jit(false).
    let sets: &[(&str, bool)] = if jit {
        &[("groups", true), ("groups_nojit", false)]
    } else {
        eprintln!("no JIT in this build: replaying the pcre.jit=0 vectors only");
        &[("groups_nojit", false)]
    };
    for &(key, with_jit) in sets {
        let mut set_cases = 0;
        for group in root[key].as_array().expect("groups") {
            let name = group["group"].as_str().expect("group name");
            let label = if with_jit {
                name.to_owned()
            } else {
                format!("nojit:{name}")
            };
            let mut pcre = Pcre::new();
            if !with_jit {
                pcre.set_jit(false);
            }
            for (index, step) in group["steps"].as_array().expect("steps").iter().enumerate() {
                if let Some(ini) = step.get("ini") {
                    apply_ini(&mut pcre, ini.as_array().expect("ini pairs"));
                } else {
                    set_cases += 1;
                    run_case(&mut pcre, &label, index, step, &mut f);
                }
            }
        }
        assert!(set_cases > 1500, "only {set_cases} cases in {key}");
        cases += set_cases;
    }
    if !f.list.is_empty() {
        let shown: Vec<&str> = f.list.iter().take(40).map(String::as_str).collect();
        panic!(
            "{} of {} checks failed ({cases} cases):\n{}",
            f.list.len(),
            f.checks,
            shown.join("\n")
        );
    }
    eprintln!("{} checks over {cases} cases passed", f.checks);
}
